import { readFileSync } from 'node:fs';
import booleanPointInPolygon from '@turf/boolean-point-in-polygon';

/**
 * Danish geography that never touches the network: the 98 kommuner and 1,089 postcodes, as files
 * generated by `tools/geo/build-denmark-geo.mjs` from DAGI (Klimadatastyrelsen) and committed under
 * `data/`. DAWA, which this used to be asked of, was shut down in October 2026.
 *
 * Everything here is synchronous and pure after the first call, which reads the two files once and
 * indexes them. Nothing can fail at run time other than the files being absent, and that is a broken
 * install rather than a condition to degrade around, so it throws.
 *
 * Accuracy: the polygons are simplified (about 200 m) for the browser, so {@link kommuneOfPoint} can
 * be wrong for a point within that distance of a border. {@link kommuneOfPostcode} was worked out
 * against the unsimplified boundaries and is exact to the generator's sampling. Prefer the postcode
 * when a record has one and a coordinate that may sit on a border.
 */

/**
 * @typedef {Object} Kommune
 * @property {string} code Four-digit kommunekode, e.g. `0101`.
 * @property {string} name
 * @property {Object} geometry GeoJSON `Polygon` / `MultiPolygon`, WGS84, simplified.
 */

/**
 * @typedef {Object} PostcodeInfo
 * @property {string} zip Four digits.
 * @property {string} name The postal town, e.g. `Hillerød` or `København K`.
 * @property {number} lat Centroid of the postcode area.
 * @property {number} lng
 * @property {Array<{code: string, share: number}>} kommuner Where the area lies, largest share first.
 *   Twenty percent of postcodes straddle a border; `share` is the part of the land in each.
 * @property {boolean} [street] A postcode for one street or one addressee (company, institution), not a place.
 * @property {boolean} [nearest] The area holds no land, so the kommune is the nearest one rather than a measured one.
 */

/**
 * @typedef {Object} ResolvedPlace
 * @property {string} zip
 * @property {string} name
 * @property {number} lat
 * @property {number} lng
 * @property {string} kommuneCode
 * @property {string} kommuneName
 */

const KOMMUNER_FILE = new URL('./data/kommuner.geojson', import.meta.url);
const POSTNUMRE_FILE = new URL('./data/postnumre.json', import.meta.url);

/** The district letters Copenhagen and a few other towns append to a postal town (`København K`, `Odense SV`). */
const DISTRICT_SUFFIX = /\s+(?:[A-ZÆØÅ]|NV|SV|SØ|NØ)$/;

/** @type {{kommuner: Array<Kommune & {bbox: number[], feature: Object}>, byCode: Map<string, Kommune>, postnumre: Map<string, PostcodeInfo>, byName: Map<string, string[]>, kommuneByName: Map<string, Kommune>, attribution: string, snapshot: string}|null} */
let loaded = null;

/**
 * Folds a Danish place name to a comparable key: lower case, `å`/`aa`, `ø`/`oe` and `æ`/`ae` made one
 * spelling, other diacritics removed, punctuation and runs of spaces collapsed. `Århus` and `Aarhus`
 * meet, as do `Ølgod` and `Oelgod`.
 *
 * @param {string} text
 * @returns {string}
 */
export function normalizePlaceName(text) {
  return String(text ?? '')
    .toLowerCase()
    .replace(/å/g, 'aa')
    .replace(/ø/g, 'oe')
    .replace(/æ/g, 'ae')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function bboxOf(geometry) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  const visit = (c) => {
    if (typeof c[0] === 'number') {
      minX = Math.min(minX, c[0]);
      maxX = Math.max(maxX, c[0]);
      minY = Math.min(minY, c[1]);
      maxY = Math.max(maxY, c[1]);
    } else {
      c.forEach(visit);
    }
  };
  visit(geometry.coordinates);
  return [minX, minY, maxX, maxY];
}

function load() {
  if (loaded) return loaded;
  const kommunerFile = JSON.parse(readFileSync(KOMMUNER_FILE, 'utf8'));
  const postnumreFile = JSON.parse(readFileSync(POSTNUMRE_FILE, 'utf8'));

  const kommuner = kommunerFile.features.map((f) => ({
    code: f.properties.code,
    name: f.properties.name,
    geometry: f.geometry,
    bbox: bboxOf(f.geometry),
    feature: f,
  }));
  const byCode = new Map(kommuner.map((k) => [k.code, k]));

  // `Aarhus Kommune`, `Københavns Kommune` and `Aarhus` all name the same place.
  const kommuneByName = new Map();
  for (const k of kommuner) {
    const key = normalizePlaceName(k.name);
    kommuneByName.set(key, k);
  }

  const postnumre = new Map();
  const byName = new Map();
  for (const [zip, p] of Object.entries(postnumreFile.postnumre)) {
    postnumre.set(zip, { zip, ...p });
    // A name is findable both whole (`københavn k`) and without its district letter (`københavn`).
    for (const name of new Set([p.name, p.name.replace(DISTRICT_SUFFIX, '')])) {
      const key = normalizePlaceName(name);
      byName.set(key, [...(byName.get(key) ?? []), zip]);
    }
  }

  loaded = {
    kommuner,
    byCode,
    postnumre,
    byName,
    kommuneByName,
    attribution: kommunerFile.attribution,
    snapshot: kommunerFile.snapshot,
  };
  return loaded;
}

/**
 * The attribution DAGI's terms ask for next to anything drawn from this data.
 *
 * @returns {string}
 */
export function getGeoAttribution() {
  return load().attribution;
}

/**
 * Every kommune with its simplified boundary. The same objects every call: do not mutate.
 *
 * @returns {Kommune[]}
 */
export function getKommunePolygons() {
  return load().kommuner.map(({ code, name, geometry }) => ({ code, name, geometry }));
}

/**
 * The kommune with this code.
 *
 * @param {string|number} code `101` and `0101` both work.
 * @returns {{code: string, name: string}|null}
 */
export function kommuneByCode(code) {
  const k = load().byCode.get(String(code).padStart(4, '0'));
  return k ? { code: k.code, name: k.name } : null;
}

/**
 * The kommune a name refers to: `Aarhus`, `Århus Kommune`, `Københavns Kommune`, `Ringkøbing-Skjern`.
 * `null` when it names none, which includes a place that is not a kommune (`Hillerød` is a town in
 * Hillerød kommune: use {@link resolvePlace} for that).
 *
 * @param {string} name
 * @returns {{code: string, name: string}|null}
 */
export function kommuneByName(name) {
  const { kommuneByName: index } = load();
  const key = normalizePlaceName(name).replace(/ kommune$/, '');
  // `København` is written `Københavns Kommune` by Nominatim, and `Frederiksbergs`, `Odenses`, ... likewise.
  const hit = index.get(key) ?? (key.endsWith('s') ? index.get(key.slice(0, -1)) : undefined);
  return hit ? { code: hit.code, name: hit.name } : null;
}

/**
 * The kommune a coordinate lies in, or `null` outside Denmark and at sea.
 *
 * @param {number} lat
 * @param {number} lng
 * @returns {{code: string, name: string}|null}
 */
export function kommuneOfPoint(lat, lng) {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  const point = [lng, lat];
  for (const k of load().kommuner) {
    const [minX, minY, maxX, maxY] = k.bbox;
    if (lng < minX || lng > maxX || lat < minY || lat > maxY) continue;
    if (booleanPointInPolygon(point, k.feature)) return { code: k.code, name: k.name };
  }
  return null;
}

/**
 * What the register says about a postcode.
 *
 * @param {string|number} zip
 * @returns {PostcodeInfo|null}
 */
export function postcodeInfo(zip) {
  const p = load().postnumre.get(String(zip).padStart(4, '0'));
  return p ? { ...p, kommuner: p.kommuner.map((k) => ({ ...k })) } : null;
}

/**
 * The kommune a postcode mostly lies in. A postcode that straddles a border names its largest part;
 * `others` carries the rest for a caller that cares.
 *
 * @param {string|number} zip
 * @returns {{code: string, name: string, share: number, others: Array<{code: string, name: string, share: number}>}|null}
 */
export function kommuneOfPostcode(zip) {
  const p = postcodeInfo(zip);
  if (!p) return null;
  const named = p.kommuner.map((k) => ({
    code: k.code,
    name: load().byCode.get(k.code)?.name ?? k.code,
    share: k.share,
  }));
  const [first, ...others] = named;
  return { ...first, others };
}

/**
 * The postcodes whose postal town matches a name.
 *
 * @param {string} name `Hillerød`, `Aarhus`, `København K`, `København`.
 * @returns {PostcodeInfo[]}
 */
export function findPostcodesByName(name) {
  const zips = load().byName.get(normalizePlaceName(name)) ?? [];
  return zips.map((z) => postcodeInfo(z));
}

/**
 * Turns the place text a job ad, a listing or a user wrote - `3400 Hillerød`, `Hillerød`, `8200 Aarhus N`,
 * `2100 København Ø` - into a postcode, a position and a kommune. `null` when it names no Danish
 * place or names several in different kommuner (`Herning, Holstebro, Skive eller Karup J`, or a
 * name that two towns share), since a wrong kommune is worse than none.
 *
 * A four-digit postcode in the text wins over the name. Postcodes for one addressee (`street`) are
 * passed over for a name match, because they are the postal address of a company, not a place - but
 * are used when the text gives the number itself.
 *
 * @param {string} text
 * @returns {ResolvedPlace|null}
 */
export function resolvePlace(text) {
  const raw = String(text ?? '').trim();
  if (!raw) return null;

  const zipMatch = raw.match(/(?<![\d])(\d{4})(?![\d])/);
  if (zipMatch) {
    const info = postcodeInfo(zipMatch[1]);
    if (info) return placeFrom(info);
  }

  // The part after a postcode, or the whole text: `3400 Hillerød` -> `Hillerød`.
  const name = raw.replace(/^\d{4}\s*/, '').trim();
  if (!name || /[,;]| eller | og /i.test(name)) return null;

  const candidates = findPostcodesByName(name).filter((p) => !p.street);
  if (!candidates.length) return null;
  const kommuner = new Set(candidates.map((c) => c.kommuner[0].code));
  if (kommuner.size > 1) return null;
  // Several postcodes in one kommune (Aarhus C/N/V): the first is a fair centre for the town.
  return placeFrom(candidates[0]);
}

function placeFrom(info) {
  const kommune = load().byCode.get(info.kommuner[0].code);
  return {
    zip: info.zip,
    name: info.name,
    lat: info.lat,
    lng: info.lng,
    kommuneCode: info.kommuner[0].code,
    kommuneName: kommune?.name ?? info.kommuner[0].code,
  };
}

/** Drops the index so the next call reloads the files. Only used by the tests. */
export function resetDenmarkGeo() {
  loaded = null;
}
